import{_ as l,a0 as u,w as r,s as p,ao as m,I as d,x as t,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const f=JSON.parse('{"title":"Linux 有问必答：如何使用yum来下载RPM包而不进行安装 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何使用yum来下载RPM包而不进行安装 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何使用yum来下载RPM包而不进行安装 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何使用yum来下载RPM包而不进行安装 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150122 Linux FAQs with Answers--How to use yum to download a RPM package without installing it","title":"Linux 有问必答：如何使用yum来下载RPM包而不进行安装","tag":"201503","desc":""},"relativePath":"201503/20150122 Linux FAQs with Answers--How to use yum to download a RPM package without installing it.md","filePath":"[post].md"}'),s={name:"201503/20150122 Linux FAQs with Answers--How to use yum to download a RPM package without installing it.md"};function i(y,o,w,x,g,c){const e=u("Link");return r(),p("div",null,[o[11]||(o[11]=m(`<h1 id="linux-有问必答-如何使用yum来下载rpm包而不进行安装" tabindex="-1">Linux 有问必答：如何使用yum来下载RPM包而不进行安装 <a class="header-anchor" href="#linux-有问必答-如何使用yum来下载rpm包而不进行安装" aria-label="Permalink to “Linux 有问必答：如何使用yum来下载RPM包而不进行安装”">​</a></h1><blockquote><p><strong>问题</strong>:我想从Red Hat 的标准仓库中下载一个RPM包，我能使用yum命令来下载一个RPM包但是不进行安装吗？</p></blockquote><p>yum是基于Red Hat的系统(如CentOS、Fedora、RHEl)上的默认包管理器。使用yum，你可以安装或者更新一个RPM包，并且他会自动解决包依赖关系。但是如果你只想将一个RPM包下载到你的系统上该怎么办呢? 例如，你可能想要获取一些RPM包在以后使用，或者将他们安装在另外的机器上。</p><p>这里说明了如何从yum仓库上下载一个RPM包。</p><h3 id="方法一-yum" tabindex="-1">方法一:yum### <a class="header-anchor" href="#方法一-yum" aria-label="Permalink to “方法一:yum###”">​</a></h3><p>yum命令本身就可以用来下载一个RPM包，标准的yum命令提供了<code>--downloadonly(只下载)</code>的选项来达到这个目的。</p><pre><code>$ sudo yum install --downloadonly &lt;package-name&gt;
</code></pre><p>默认情况下，一个下载的RPM包会保存在下面的目录中:</p><pre><code>/var/cache/yum/x86_64/[centos/fedora-version]/[repository]/packages
</code></pre><p>以上的[repository]表示下载包的来源仓库的名称(例如：base、fedora、updates)</p><p>如果你想要将一个包下载到一个指定的目录(如/tmp)：</p><pre><code>$ sudo yum install --downloadonly --downloaddir=/tmp &lt;package-name&gt;
</code></pre><p>注意，如果下载的包包含了任何没有满足的依赖关系，yum将会把所有的依赖关系包下载，但是都不会被安装。</p><p>另外一个重要的事情是，在CentOS/RHEL 6或更早期的版本中，你需要安装一个单独yum插件(名称为 yum-plugin-downloadonly)才能使用<code>--downloadonly</code>命令选项：</p><pre><code>$ sudo yum install yum-plugin-downloadonly
</code></pre><p>如果没有该插件，你会在使用yum时得到以下错误：</p><pre><code>Command line error: no such option: --downloadonly
</code></pre><p><img src="https://farm9.staticflickr.com/8627/15571201803_38390aae75_c.jpg" alt=""></p><h3 id="方法二-yumdownloader" tabindex="-1">方法二: Yumdownloader### <a class="header-anchor" href="#方法二-yumdownloader" aria-label="Permalink to “方法二: Yumdownloader###”">​</a></h3><p>另外一个下载RPM包的方法就是通过一个专门的包下载工具--yumdownloader。 这个工具是yum工具包(包含了用来进行yum包管理的帮助工具套件)的子集。</p><pre><code>$ sudo yum install yum-utils
</code></pre><p>下载一个RPM包：</p><pre><code>$ sudo yumdownloader &lt;package-name&gt;
</code></pre><p>下载的包会被保存在当前目录中。你需要使用root权限，因为yumdownloader会在下载过程中更新包索引文件。与yum命令不同的是，任何依赖包不会被下载。</p><hr>`,25)),d("p",null,[o[1]||(o[1]=t("via: ",-1)),a(e,{href:"http://ask.xmodulo.com/yum-download-rpm-package.html"},{default:n(()=>[...o[0]||(o[0]=[t("http://ask.xmodulo.com/yum-download-rpm-package.html",-1)])]),_:1})]),d("p",null,[o[4]||(o[4]=t("译者：",-1)),a(e,{href:"https://github.com/theo-l"},{default:n(()=>[...o[2]||(o[2]=[t("theo-l",-1)])]),_:1}),o[5]||(o[5]=t(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:n(()=>[...o[3]||(o[3]=[t("wxy",-1)])]),_:1})]),d("p",null,[o[8]||(o[8]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...o[6]||(o[6]=[t("LCTT",-1)])]),_:1}),o[9]||(o[9]=t(" 原创翻译，",-1)),a(e,{href:"http://linux.cn/"},{default:n(()=>[...o[7]||(o[7]=[t("Linux中国",-1)])]),_:1}),o[10]||(o[10]=t(" 荣誉推出",-1))])])}const R=l(s,[["render",i]]);export{f as __pageData,R as default};
